**counter.go**

```go
package lesson

func Double(value int) int { return value * 2 }

type Counter struct{ value int }

func (c *Counter) Add(delta int) { c.value += delta }
func (c Counter) Value() int     { return c.value }
```

**counter_test.go**

```go
package lesson

import "fmt"

func Example() {
	fmt.Println("lesson package")
	// Output: lesson package
}

func ExampleDouble() {
	fmt.Println(Double(4))
	// Output: 8
}

func ExampleCounter() {
	var counter Counter
	fmt.Println(counter.Value())
	// Output: 0
}

func ExampleCounter_Add() {
	var counter Counter
	counter.Add(3)
	fmt.Println(counter.Value())
	// Output: 3
}
```

**Run it**

```bash
go test -v ./...
go vet ./...
```

Each function name points to a declaration that exists in `counter.go`; vet can therefore confirm the intended associations.

**labels.go**

```go
package lesson

func Labels() map[string]int {
	return map[string]int{"ready": 1, "waiting": 2}
}
```

**labels_test.go**

```go
package lesson

import "fmt"

func ExampleLabels() {
	for label, value := range Labels() {
		fmt.Println(label, value)
	}
	// Unordered output:
	// ready 1
	// waiting 2
}

func Example_unchecked() {
	fmt.Println("this example is compiled but not executed")
}
```

**Run it**

```bash
go test -v ./...
go vet ./...
```

The map example checks both lines without pretending map iteration has stable order. The suffix-only package example has no runtime oracle.
